<style>.lavka-media-help{margin:20px 0 26px;padding:24px;border:1px solid #c8d9df;border-radius:16px;background:linear-gradient(125deg,#f0f9f7,#fff 65%);max-width:1200px;box-sizing:border-box}.lavka-media-help h2{font-size:23px;margin:0 0 10px;color:#163d42}.lavka-media-help p{font-size:14px;line-height:1.65}.lavka-media-help .lm-steps{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px;counter-reset:steps;margin:20px 0;padding:0;list-style:none}.lavka-media-help .lm-steps li{padding:16px;background:#fff;border:1px solid #dbe6e9;border-radius:12px;line-height:1.6}.lavka-media-help .lm-steps li:before{counter-increment:steps;content:counter(steps);display:block;background:#166963;color:white;width:28px;line-height:28px;text-align:center;border-radius:50%;margin-bottom:10px;font-weight:700}.lavka-media-help details{border-top:1px solid #d5e2e4;padding:13px 0}.lavka-media-help summary{font-weight:600;font-size:14px;cursor:pointer;padding:5px}.lavka-media-help summary:focus-visible,.lavka-media-help a:focus-visible{outline:3px solid #2271b1;outline-offset:3px}.lavka-media-help table{border-collapse:collapse;width:100%;background:white}.lavka-media-help th,.lavka-media-help td{text-align:left;padding:10px;border:1px solid #dbe6e9}.lavka-media-help .lm-table{overflow-x:auto}.lavka-media-help .lm-links{display:flex;gap:10px;flex-wrap:wrap;margin-top:14px}.lavka-media-help .lm-note{border-left:4px solid #b77e14;padding:10px 14px;background:#fff8e8}@media(max-width:900px){.lavka-media-help .lm-steps{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:600px){.lavka-media-help{padding:16px}.lavka-media-help .lm-steps{grid-template-columns:1fr}}</style>
<section class="lavka-media-help" aria-labelledby="lm-help-title"><h2 id="lm-help-title"><?php echo esc_html__('How to work with product images', 'lavka-product-media-upload'); ?></h2><ol class="lm-steps"><li><strong><?php echo esc_html__('Prepare the files', 'lavka-product-media-upload'); ?></strong><p><?php echo esc_html__('Download the XLSX template below. Fill it in and select the matching JPEG, PNG or WebP files.', 'lavka-product-media-upload'); ?></p></li><li><strong><?php echo esc_html__('Check the batch', 'lavka-product-media-upload'); ?></strong><p><?php echo esc_html__('Run the check first. Images and product links are not changed at this stage.', 'lavka-product-media-upload'); ?></p></li><li><strong><?php echo esc_html__('Review and upload', 'lavka-product-media-upload'); ?></strong><p><?php echo esc_html__('Review READY rows and warnings, save the CSV report, then confirm the upload. Do not change the inputs after checking.', 'lavka-product-media-upload'); ?></p></li><li><strong><?php echo esc_html__('Verify the result', 'lavka-product-media-upload'); ?></strong><p><?php echo esc_html__('Save the final CSV. Check the main photo and gallery order on the product page.', 'lavka-product-media-upload'); ?></p></li></ol><details><summary><?php echo esc_html__('How to fill in the XLSX registry', 'lavka-product-media-upload'); ?></summary><p><?php echo esc_html__('One row describes one image assignment. Keep SKU and barcode cells as text to preserve leading zeroes.', 'lavka-product-media-upload'); ?></p><div class="lm-table"><table><thead><tr><th scope="col"><?php echo esc_html__('Column', 'lavka-product-media-upload'); ?></th><th scope="col"><?php echo esc_html__('What to enter', 'lavka-product-media-upload'); ?></th></tr></thead><tbody><tr><th scope="row"><code>sku</code></th><td><?php echo esc_html__('Exact SKU on our website and in Folio.', 'lavka-product-media-upload'); ?></td></tr><tr><th scope="row"><code>barcode</code></th><td><?php echo esc_html__('Barcode; may be empty when SKU is provided.', 'lavka-product-media-upload'); ?></td></tr><tr><th scope="row"><code>source_file</code></th><td><?php echo esc_html__('Exact local filename including its extension, for example front.jpg.', 'lavka-product-media-upload'); ?></td></tr><tr><th scope="row"><code>role</code></th><td><?php echo esc_html__('main for the main image; gallery for an additional image.', 'lavka-product-media-upload'); ?></td></tr><tr><th scope="row"><code>position</code></th><td><?php echo esc_html__('Leave empty for main. For gallery use unique positions 1, 2, 3.', 'lavka-product-media-upload'); ?></td></tr></tbody></table></div><p><?php echo esc_html__('Use only one main image per product. Standard variations support a main image only. Automatic naming creates the website filename without renaming your local original.', 'lavka-product-media-upload'); ?></p></details><details><summary><?php echo esc_html__('What do the check results mean?', 'lavka-product-media-upload'); ?></summary><p><?php echo esc_html__('READY: review the product and role, then upload. Warnings need attention. Errors block the row: correct the file or registry and check again.', 'lavka-product-media-upload'); ?></p></details><details><summary><?php echo esc_html__('What if the image already exists?', 'lavka-product-media-upload'); ?></summary><p><?php echo esc_html__('A verified identical image with a valid Media Library record can be reused. The same filename with different content is blocked. An S3-only file needs an administrator to restore its Media Library record. Do not add -1 or upload a duplicate manually.', 'lavka-product-media-upload'); ?></p></details><details><summary><?php echo esc_html__('How do I confirm success or recover from an interruption?', 'lavka-product-media-upload'); ?></summary><p><?php echo esc_html__('Success requires SUCCESS, completed and Folio applied/noop, with no errors. Save the final CSV and check the storefront. After a timeout, keep the report and ask the administrator to establish the result before retrying. Once resolved, recheck the same registry and files.', 'lavka-product-media-upload'); ?></p></details><nav class="lm-links" aria-label="<?php echo esc_html__('Image workflow navigation', 'lavka-product-media-upload'); ?>"><a class="button" href="<?php echo esc_url($template_url); ?>"><?php echo esc_html__('Download XLSX template', 'lavka-product-media-upload'); ?></a><a class="button" href="<?php echo esc_url(admin_url('admin.php?page=lts-media#lts_media_missing_report')); ?>"><?php echo esc_html__('Check existing product images', 'lavka-product-media-upload'); ?></a></nav></section>
